import torch
import torch.nn as nn
from cutegen.ptx_runtime import PtxModule, i32, u32, i64, u64, f32, f64

PTX_SOURCE = r"""
.version 8.0
.target sm_89
.address_size 64

.visible .entry the_entry_name(
    .param .u64 x_ptr,
    .param .u64 w_ptr,
    .param .u64 b_ptr,
    .param .u64 y_ptr,
    .param .u32 pN,
    .param .u32 pC,
    .param .u32 pH,
    .param .u32 pW,
    .param .u32 pOC,
    .param .u32 pKH,
    .param .u32 pKW,
    .param .u32 pOH,
    .param .u32 pOW,
    .param .u32 pSTRH,
    .param .u32 pSTRW,
    .param .u32 pPADH,
    .param .u32 pPADW
)
{
    .reg .pred %p<8>;
    .reg .u32 %r<64>;
    .reg .u64 %rd<32>;
    .reg .s32 %s<16>;
    .reg .f32 %f<8>;

    // Load pointers
    ld.param.u64 %rd0, [x_ptr];
    ld.param.u64 %rd1, [w_ptr];
    ld.param.u64 %rd2, [b_ptr];
    ld.param.u64 %rd3, [y_ptr];

    // Load scalars
    ld.param.u32 %r10, [pN];
    ld.param.u32 %r11, [pC];
    ld.param.u32 %r12, [pH];
    ld.param.u32 %r13, [pW];
    ld.param.u32 %r14, [pOC];
    ld.param.u32 %r15, [pKH];
    ld.param.u32 %r16, [pKW];
    ld.param.u32 %r17, [pOH];
    ld.param.u32 %r18, [pOW];
    ld.param.u32 %r19, [pSTRH];
    ld.param.u32 %r20, [pSTRW];
    ld.param.u32 %r21, [pPADH];
    ld.param.u32 %r22, [pPADW];

    // Compute global thread id
    mov.u32 %r0, %tid.x;
    mov.u32 %r1, %ntid.x;
    mov.u32 %r2, %ctaid.x;
    mad.lo.u32 %r3, %r2, %r1, %r0; // r3 = gid

    // total = N*OC*OH*OW
    mul.lo.u32 %r4, %r10, %r14;      // N*OC
    mul.lo.u32 %r4, %r4,  %r17;      // *OH
    mul.lo.u32 %r4, %r4,  %r18;      // *OW

    setp.ge.u32 %p0, %r3, %r4;
    @%p0 bra DONE;

    // Decompose gid into indices
    mov.u32 %r5, %r3;                // id working

    // ow = id % OW
    rem.u32 %r30, %r5, %r18;
    div.u32 %r5, %r5, %r18;

    // oh = id % OH
    rem.u32 %r29, %r5, %r17;
    div.u32 %r5, %r5, %r17;

    // oc = id % OC
    rem.u32 %r28, %r5, %r14;
    div.u32 %r27, %r5, %r14;        // n = id / OC

    // Load bias into sum
    mul.wide.u32 %rd10, %r28, 4;
    add.u64 %rd11, %rd2, %rd10;
    ld.global.f32 %f0, [%rd11];     // sum

    // Cast constants to s32 for comparisons
    cvt.s32.u32 %s10, %r21;  // PADH
    cvt.s32.u32 %s11, %r22;  // PADW
    cvt.s32.u32 %s12, %r12;  // H
    cvt.s32.u32 %s13, %r13;  // W

    // c = 0
    mov.u32 %r31, 0;

C_LOOP:
    setp.ge.u32 %p1, %r31, %r11;
    @%p1 bra C_DONE;

    // kh = 0
    mov.u32 %r32, 0;

KH_LOOP:
    setp.ge.u32 %p2, %r32, %r15;
    @%p2 bra C_NEXT;

    // sih = (oh*STRH + kh - PADH)
    mul.lo.u32 %r40, %r29, %r19;   // oh*STRH
    cvt.s32.u32 %s0, %r40;
    cvt.s32.u32 %s1, %r32;         // kh
    add.s32 %s2, %s0, %s1;
    sub.s32 %s2, %s2, %s10;        // s2 = sih

    // if (sih < 0 || sih >= H) goto KH_INC
    setp.lt.s32 %p3, %s2, 0;
    @%p3 bra KH_INC;
    setp.ge.s32 %p4, %s2, %s12;
    @%p4 bra KH_INC;

    // ih_u32 = (u32)sih
    cvt.u32.s32 %r41, %s2;

    // kw = 0
    mov.u32 %r33, 0;

KW_LOOP:
    setp.ge.u32 %p5, %r33, %r16;
    @%p5 bra KH_INC;

    // siw = (ow*STRW + kw - PADW)
    mul.lo.u32 %r42, %r30, %r20;  // ow*STRW
    cvt.s32.u32 %s3, %r42;
    cvt.s32.u32 %s4, %r33;        // kw
    add.s32 %s5, %s3, %s4;
    sub.s32 %s5, %s5, %s11;       // siw

    setp.lt.s32 %p6, %s5, 0;
    @%p6 bra KW_INC;
    setp.ge.s32 %p7, %s5, %s13;
    @%p7 bra KW_INC;

    // iw_u32
    cvt.u32.s32 %r43, %s5;

    // x index: (((n*C + c)*H + ih)*W + iw)
    // t0 = n*C + c
    mul.lo.u32 %r50, %r27, %r11;
    add.u32 %r50, %r50, %r31;
    // t1 = t0*H + ih
    mul.lo.u32 %r51, %r50, %r12;
    add.u32 %r51, %r51, %r41;
    // t2 = t1*W + iw
    mul.lo.u32 %r52, %r51, %r13;
    add.u32 %r52, %r52, %r43;

    // addr_x
    mul.wide.u32 %rd12, %r52, 4;
    add.u64 %rd13, %rd0, %rd12;
    ld.global.f32 %f1, [%rd13];

    // w index: ((((oc*C)+c)*KH + kh)*KW + kw)
    mul.lo.u32 %r53, %r28, %r11; // oc*C
    add.u32 %r53, %r53, %r31;    // + c
    mul.lo.u32 %r54, %r53, %r15; // *KH
    add.u32 %r54, %r54, %r32;    // + kh
    mul.lo.u32 %r55, %r54, %r16; // *KW
    add.u32 %r55, %r55, %r33;    // + kw

    mul.wide.u32 %rd14, %r55, 4;
    add.u64 %rd15, %rd1, %rd14;
    ld.global.f32 %f2, [%rd15];

    // sum += x * w
    fma.rn.f32 %f0, %f1, %f2, %f0;

KW_INC:
    add.u32 %r33, %r33, 1;
    bra KW_LOOP;

KH_INC:
    add.u32 %r32, %r32, 1;
    bra KH_LOOP;

C_NEXT:
    add.u32 %r31, %r31, 1;
    bra C_LOOP;

C_DONE:
    // y index: (((n*OC + oc)*OH + oh)*OW + ow)
    mul.lo.u32 %r60, %r27, %r14; // n*OC
    add.u32 %r60, %r60, %r28;    // + oc
    mul.lo.u32 %r61, %r60, %r17; // *OH
    add.u32 %r61, %r61, %r29;    // + oh
    mul.lo.u32 %r62, %r61, %r18; // *OW
    add.u32 %r62, %r62, %r30;    // + ow

    mul.wide.u32 %rd20, %r62, 4;
    add.u64 %rd21, %rd3, %rd20;
    st.global.f32 [%rd21], %f0;

DONE:
    ret;
}
"""

_ptx_module = None

def _get_ptx_module():
    global _ptx_module
    if _ptx_module is None:
        _ptx_module = PtxModule(PTX_SOURCE)
    return _ptx_module

def validate_generated_code():
    # Force PTX JIT assembly and entry-point lookup during compile validation.
    _get_ptx_module().function("the_entry_name")

class ModelNew(nn.Module):
    def __init__(self, num_classes=1000):
        super().__init__()
        # Match the reference constructor and parameters exactly.
        self.conv1 = nn.Conv2d(in_channels=3, out_channels=96, kernel_size=11, stride=4, padding=2)

    def forward(self, x):
        # Allocate output tensors with torch.empty only.
        # Launch PTX on the current PyTorch stream and return the output.
        assert x.is_cuda, "Input must be on CUDA device"
        assert x.dtype == torch.float32, "Only float32 tensors are supported"
        w = self.conv1.weight
        b = self.conv1.bias

        N, C, H, W = x.shape
        OC, _, KH, KW = w.shape

        stride = self.conv1.stride if isinstance(self.conv1.stride, tuple) else (self.conv1.stride, self.conv1.stride)
        padding = self.conv1.padding if isinstance(self.conv1.padding, tuple) else (self.conv1.padding, self.conv1.padding)
        SH, SW = int(stride[0]), int(stride[1])
        PH, PW = int(padding[0]), int(padding[1])

        OH = (H + 2 * PH - KH) // SH + 1
        OW = (W + 2 * PW - KW) // SW + 1

        y = torch.empty((N, OC, OH, OW), device=x.device, dtype=x.dtype)

        module = _get_ptx_module()
        TPB = 256
        total = N * OC * OH * OW
        grid_x = (total + TPB - 1) // TPB

        module.launch(
            "the_entry_name",
            grid=(grid_x, 1, 1),
            block=(TPB, 1, 1),
            arguments=[
                x, w, b, y,
                u32(N), u32(C), u32(H), u32(W),
                u32(OC), u32(KH), u32(KW), u32(OH), u32(OW),
                u32(SH), u32(SW), u32(PH), u32(PW),
            ],
            shared_memory=0,
            stream=torch.cuda.current_stream(x.device),
        )
        return y

